helpers.cm_powmod:
func cm_powmod(a int64, b int64, m int64) int64 {
	r := cm_floormod(1, m)
	a = cm_floormod(a, m)
	for b > 0 {
		if b&1 == 1 {
			r = cm_floormod(r*a, m)
		}
		a = cm_floormod(a*a, m)
		b >>= 1
	}
	return r
}
